<?php

class Fibonacci {
	private $mod;
	private $calculatedNumbers;

	public function __construct($mod) {
		$this->calculatedNumbers = array();
		$this->calculatedNumbers[0] = 1;
		$this->calculatedNumbers[1] = 1;
		$this->mod = $mod;
	}

	public function fib($n) {
		if (array_key_exists($n, $this->calculatedNumbers)) return $this->calculatedNumbers[$n];

		$k = intdiv($n, 2);
		if ($n % 2 == 0) {
			$res = ($this->fib($k) * $this->fib($k) + $this->fib($k - 1) * $this->fib($k - 1)) % $this->mod;
		} else {
			$res = ($this->fib($k) * $this->fib($k + 1) + $this->fib($k - 1) * $this->fib($k)) % $this->mod;
		}
		$this->calculatedNumbers[$n] = $res;
		return $res;
	}
}

class Exponentation {
	// a^b mod m
	public static function calc($a, $b, $m) {
		if ($b == 0) return 1;
		if ($b == 1) return $a;
		if ($b % 2 == 0) return self::calc($a * $a % $m, intdiv($b, 2), $m);
		else return $a * self::calc($a * $a % $m, intdiv($b - 1, 2), $m) % $m;
	}
}

class Solver {
	public $n, $k, $l, $MOD;

	function read($in) {
		$this->n = $in->nextLong();
		$this->k = $in->nextLong();
		$this->l = $in->nextLong();
		$this->MOD = $in->nextLong();
	}

	public function solve($in, $out) {
		$this->read($in);
		if ($this->l != 64 && ((1 << $this->l) - 1) < $this->k) {
			$out->println(0);
			return;
		}

		$fibonacci = new Fibonacci($this->MOD);
		$zeroPos = $fibonacci->fib($this->n + 1);
		$onePos = Exponentation::calc(2, $this->n, $this->MOD) - $zeroPos;
		while ($onePos < 0) $onePos += $this->MOD;

		$res = 1;
		for ($i = 0; $i < $this->l; $i++) {
			if (($this->k & (1 << $i)) != 0) $res *= $onePos;
			else $res *= $zeroPos;
			$res %= $this->MOD;
		}
		$out->println($res % $this->MOD);
	}
}

class InputReader {
	public $stream;
	public $currentLine;
	public $token;

	public function __construct($stream) {
		$this->stream = $stream;
		$this->currentLine = null;
		$this->token = 0;
	}

	public function next() {
		while ($this->currentLine === null || $this->token >= count($this->currentLine)) {
			$line = fgets($this->stream);
			if ($line === false) break;
			$this->currentLine = preg_split("/\\s+/", trim($line));
			$this->token = 0;
		}
		return $this->currentLine[$this->token++];
	}

	public function nextInt() {
		return intval($this->next());
	}

	public function nextLong() {
		return intval($this->next());
	}
}

class PrintWriter {
	public $stream;

	public function __construct($stream) {
		$this->stream = $stream;
	}

	public function println($s) {
		fwrite($this->stream, $s . "\n");
	}

	public function close() {
		fflush($this->stream);
	}
}

